-- ---------- the lost update, under the default isolation level ----------
-- Session A                          | Session B
BEGIN;                                | BEGIN;
SELECT balance FROM account           | SELECT balance FROM account
WHERE id = 1;          -- 100         | WHERE id = 1;          -- 100
                                      |
UPDATE account SET balance = 100 - 30 | UPDATE account SET balance = 100 - 50
WHERE id = 1;          -- 70          | WHERE id = 1;          -- 50
COMMIT;                               | COMMIT;
-- Final balance: 50. The 30 withdrawal vanished. No error was raised anywhere.


-- ---------- fix 1: lock the row when you read it ----------
BEGIN;
SELECT balance FROM account WHERE id = 1 FOR UPDATE;   -- B now WAITS here
UPDATE account SET balance = balance - 30 WHERE id = 1;
COMMIT;                                                 -- B proceeds, reads 70


-- ---------- fix 2: compute in the database, never read-then-write ----------
-- Atomic on its own. No read-modify-write window exists.
UPDATE account SET balance = balance - 30
WHERE  id = 1 AND balance >= 30;
-- Check the affected row count: zero means insufficient funds.


-- ---------- fix 3: serializable, with a retry ----------
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT balance FROM account WHERE id = 1;
UPDATE account SET balance = balance - 30 WHERE id = 1;
COMMIT;
-- May fail with a serialization_failure (SQLSTATE 40001). That is EXPECTED,
-- not a bug — but the application must catch it and retry, or the operation
-- is silently lost.


-- ---------- keep transactions short ----------
-- WRONG: holds locks across a network call of unknown duration.
BEGIN;
UPDATE orders SET status = 'Paid' WHERE order_id = 1;
-- ... application calls the payment provider here ...
COMMIT;

-- RIGHT: do the slow work first, then open a short transaction.
-- (payment provider called BEFORE this block)
BEGIN;
UPDATE orders SET status = 'Paid', payment_ref = 'pay_123' WHERE order_id = 1;
INSERT INTO payment_audit (order_id, provider_ref) VALUES (1, 'pay_123');
COMMIT;

-- ---------- a deadlock, step by step ----------
-- Session A                             | Session B
BEGIN;                                   | BEGIN;
UPDATE account SET balance = balance - 10|
WHERE id = 1;        -- locks row 1      | UPDATE account SET balance = balance - 20
                                         | WHERE id = 2;        -- locks row 2
UPDATE account SET balance = balance + 10|
WHERE id = 2;        -- WAITS for B      | UPDATE account SET balance = balance + 20
                                         | WHERE id = 1;        -- WAITS for A
-- Cycle. The database kills one with SQLSTATE 40P01.


-- ---------- the fix: a consistent lock order ----------
-- Every transaction touching several accounts locks them in ascending id order,
-- so a cycle cannot form. Both sessions now queue instead of deadlocking.
BEGIN;
SELECT * FROM account WHERE id IN (1, 2) ORDER BY id FOR UPDATE;
UPDATE account SET balance = balance - 10 WHERE id = 1;
UPDATE account SET balance = balance + 10 WHERE id = 2;
COMMIT;


-- ---------- a missing index causing deadlocks ----------
-- Without an index on status, this update may lock far more rows than it
-- changes, because the database cannot identify them precisely.
UPDATE orders SET priority = 'High' WHERE status = 'Pending';

CREATE INDEX ix_orders_status ON orders (status);
-- The deadlocks often disappear entirely. This surprises people.


-- ---------- contention without deadlock: the hot row ----------
-- Every request updates the SAME row. No deadlock, but everything queues.
UPDATE counters SET total = total + 1 WHERE name = 'page_views';

-- Better: append, and aggregate on read or on a schedule.
INSERT INTO counter_event (name, occurred_at) VALUES ('page_views', now());
-- SELECT COUNT(*) FROM counter_event WHERE name = 'page_views';


-- ---------- see live contention (Postgres) ----------
SELECT blocked.pid          AS blocked_pid,
       blocked.query        AS blocked_query,
       blocking.pid         AS blocking_pid,
       blocking.query       AS blocking_query,
       now() - blocked.query_start AS blocked_for
FROM   pg_stat_activity blocked
JOIN   pg_stat_activity blocking
       ON blocking.pid = ANY(pg_blocking_pids(blocked.pid))
WHERE  cardinality(pg_blocking_pids(blocked.pid)) > 0;

-- ---------- V1: expand ----------
-- Nullable, no default: fast, no table rewrite, no lock held.
ALTER TABLE customer ADD COLUMN email_normalised VARCHAR(320);
-- Deploy: application writes BOTH columns, still reads the old one.


-- ---------- V2: migrate, in batches ----------
-- One big UPDATE would lock millions of rows and bloat the transaction log.
DO $$
DECLARE updated INTEGER;
BEGIN
  LOOP
    UPDATE customer SET email_normalised = LOWER(TRIM(email))
    WHERE  customer_id IN (
        SELECT customer_id FROM customer
        WHERE  email_normalised IS NULL
        LIMIT  10000
    );
    GET DIAGNOSTICS updated = ROW_COUNT;
    EXIT WHEN updated = 0;
    COMMIT;                  -- release locks between batches
  END LOOP;
END $$;


-- ---------- V3: switch ----------
-- Deploy: application now READS the new column. Old version is gone.
-- Built concurrently so writes continue during the build.
CREATE UNIQUE INDEX CONCURRENTLY ux_customer_email_normalised
    ON customer (email_normalised);

-- Validated separately, so the table is not locked while it is checked.
ALTER TABLE customer ADD CONSTRAINT ck_email_normalised_present
    CHECK (email_normalised IS NOT NULL) NOT VALID;
ALTER TABLE customer VALIDATE CONSTRAINT ck_email_normalised_present;


-- ---------- V4: contract, in a LATER release ----------
ALTER TABLE customer DROP COLUMN email;


-- ---------- the operational checks that matter ----------
-- Age of the last successful backup. The alert people forget, and the one
-- that matters most on the worst day.
SELECT now() - MAX(completed_at) AS since_last_backup FROM backup_log
WHERE  status = 'Success';

-- Disk headroom.
SELECT pg_size_pretty(pg_database_size(current_database())) AS db_size;

-- Replication lag.
SELECT client_addr, state,
       pg_wal_lsn_diff(sent_lsn, replay_lsn) AS bytes_behind
FROM   pg_stat_replication;

-- Long-running transactions: they hold locks and prevent cleanup.
SELECT pid, now() - xact_start AS duration, state, query
FROM   pg_stat_activity
WHERE  xact_start < now() - INTERVAL '5 minutes'
ORDER  BY xact_start;
